Bậc của đa thức là $10$, hệ số cao nhất là $-3$, hệ số tự do là $12$
}\end{ex}

\begin{ex}%[7D7H2]
Tìm bậc, hệ số cao nhất, hệ số tự do của đa thức $- 13 x^{15}+4 x^{14}- x^{9}+6 - 13 x^{15}$
\choice
{ Bậc của đa thức là $14$, hệ số cao nhất là $-13$, hệ số tự do là $6$ }
   { Bậc của đa thức là $29$, hệ số cao nhất là $-26$, hệ số tự do là $6$ }
     { Bậc của đa thức là $15$, hệ số cao nhất là $-13$, hệ số tự do là $6$ }
    { \True Bậc của đa thức là $15$, hệ số cao nhất là $-26$, hệ số tự do là $6$  }
\loigiai{
Thu gọn đa thức $- 13 x^{15}+4 x^{14}- x^{9}+6 - 13 x^{15} =- 26 x^{15} + 4 x^{14} - x^{9} + 6$\\
Bậc của đa thức là $15$, hệ số cao nhất là $-26$, hệ số tự do là $6$
}\end{ex}

\begin{ex}%[7D7H2]
Tìm bậc, hệ số cao nhất, hệ số tự do của đa thức $- 2 x^{9}- 4 x^{6}- 15 x^{4}+12 x^{9} - 11$
\choice
{ Bậc của đa thức là $15$, hệ số cao nhất là $10$, hệ số tự do là $-11$ }
   { Bậc của đa thức là $9$, hệ số cao nhất là $-2$, hệ số tự do là $-11$ }
     { \True Bậc của đa thức là $9$, hệ số cao nhất là $10$, hệ số tự do là $-11$  }
    { Bậc của đa thức là $6$, hệ số cao nhất là $10$, hệ số tự do là $-11$ }
\loigiai{
Thu gọn đa thức $- 2 x^{9}- 4 x^{6}- 15 x^{4}+12 x^{9} - 11 =10 x^{9} - 4 x^{6} - 15 x^{4} - 11$\\
Bậc của đa thức là $9$, hệ số cao nhất là $10$, hệ số tự do là $-11$
}\end{ex}

\begin{ex}%[7D7H2]
Tìm bậc, hệ số cao nhất, hệ số tự do của đa thức $- 6 x^{16}- 5 x^{13}+12 x^{8}- 2 x^{16} - 7$
\choice
{ Bậc của đa thức là $16$, hệ số cao nhất là $-6$, hệ số tự do là $-7$ }
   { Bậc của đa thức là $13$, hệ số cao nhất là $-6$, hệ số tự do là $-7$ }
     { Bậc của đa thức là $13$, hệ số cao nhất là $-8$, hệ số tự do là $-7$ }
    { \True Bậc của đa thức là $16$, hệ số cao nhất là $-8$, hệ số tự do là $-7$  }
\loigiai{
Thu gọn đa thức $- 6 x^{16}- 5 x^{13}+12 x^{8}- 2 x^{16} - 7 =- 8 x^{16} - 5 x^{13} + 12 x^{8} - 7$\\
Bậc của đa thức là $16$, hệ số cao nhất là $-8$, hệ số tự do là $-7$
}\end{ex}

\begin{ex}%[7D7H2]
Tìm bậc, hệ số cao nhất, hệ số tự do của đa thức $4 x^{15}+7 x^{12}+6 x^{4}+7 x^{15} + 1$
\choice
{ Bậc của đa thức là $12$, hệ số cao nhất là $11$, hệ số tự do là $1$ }
   { Bậc của đa thức là $27$, hệ số cao nhất là $11$, hệ số tự do là $1$ }
     { Bậc của đa thức là $15$, hệ số cao nhất là $4$, hệ số tự do là $1$ }
    { \True Bậc của đa thức là $15$, hệ số cao nhất là $11$, hệ số tự do là $1$  }
\loigiai{
Thu gọn đa thức $4 x^{15}+7 x^{12}+6 x^{4}+7 x^{15} + 1 =11 x^{15} + 7 x^{12} + 6 x^{4} + 1$\\
Bậc của đa thức là $15$, hệ số cao nhất là $11$, hệ số tự do là $1$
}\end{ex}
